1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { AutoRefresh } from "@/components/AutoRefresh";
5	import { EmptyState, StatusDot } from "@/components/ui/primitives";
6	import { PortalHero } from "@/components/portal/PortalHero";
7	import { DeployButton } from "@/components/customer/DeployButton";
8	import { GAME_DISPLAY } from "@/lib/games";
9	import { FreeMinecraftTabContent } from "@/components/customer/freemc/FreeMinecraftTabContent";
10	
11	export const dynamic = "force-dynamic";
12	
13	// Manage-existing view only. The deploy/checkout wizard (GameDeployWizard) now lives
14	// solely on /dashboard/deploy?product=game — a single source of truth for the
15	// money-audited flow. This page lists + manages the customer's existing game servers.
16	//
17	// Two tabs, picked via ?tab= so only the active one's data actually gets fetched
18	// (the Free Minecraft tab does an SSH status round-trip to freemc-host — no reason
19	// to pay that cost on every games-page view when most people are looking at their
20	// paid servers). "Free Minecraft" used to be its own sidebar entry; it moved here
21	// and the sidebar now shows a green "FREE" tag on Game Servers instead (see
22	// app/dashboard/layout.tsx). /dashboard/free-minecraft itself still works — the
23	// marketing site and the public server directory deep-link straight to it.
24	export default async function DashboardGamesPage({
25	  searchParams,
26	}: {
27	  searchParams: Promise<{ tab?: string }>;
28	}) {
29	  const { tab } = await searchParams;
30	  const activeTab = tab === "free" ? "free" : "servers";
31	  const user = await requireUser();
32	
33	  return (
34	    <div className="space-y-6">
35	      <PortalHero
36	        variant="games"
37	        title="Game servers"
38	        sub="Your ready-to-play game servers — sized and priced per game."
39	      >
40	        <DeployButton href="/dashboard/deploy?product=game">Deploy game server</DeployButton>
41	      </PortalHero>
42	
43	      <div className="flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/80 p-1">
44	        <Link
45	          href="/dashboard/games"
46	          className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
47	            activeTab === "servers"
48	              ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white"
49	              : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
50	          }`}
51	        >
52	          My Servers
53	        </Link>
54	        <Link
55	          href="/dashboard/games?tab=free"
56	          className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
57	            activeTab === "free"
58	              ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white"
59	              : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
60	          }`}
61	        >
62	          Free Minecraft
63	          <span className="ml-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-emerald-300">
64	            Free
65	          </span>
66	        </Link>
67	      </div>
68	
69	      {activeTab === "free" ? (
70	        <FreeMinecraftTabContent />
71	      ) : (
72	        <PaidGameServers userId={user.id} />
73	      )}
74	    </div>
75	  );
76	}
77	
78	async function PaidGameServers({ userId }: { userId: string }) {
79	  const servers = await db.server.findMany({
80	    where: { userId, gamePlanId: { not: null } },
81	    include: { plan: true, osTemplate: true, gamePlan: true },
82	    orderBy: { createdAt: "desc" },
83	  });
84	
85	  const transitional = servers.some((s) =>
86	    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
87	  );
88	
89	  return (
90	    <>
91	      {transitional && <AutoRefresh />}
92	      {servers.length === 0 ? (
93	        <EmptyState
94	          title="No game servers yet"
95	          sub="Spin up a ready-to-play Minecraft, Rust, Valheim or Palworld server in minutes."
96	          action={
97	            <DeployButton href="/dashboard/deploy?product=game">Deploy your first game server</DeployButton>
98	          }
99	        />
100	      ) : (
101	        <div className="grid gap-3 sm:grid-cols-2">
102	          {servers.map((s) => {
103	            const family = s.osTemplate.family;
104	            const meta = GAME_DISPLAY[family as keyof typeof GAME_DISPLAY] ?? { name: family, glyph: "🎮" };
105	            return (
106	              <Link
107	                key={s.id}
108	                href={`/dashboard/servers/${s.id}`}
109	                className="card card-hover block transition"
110	              >
111	                <div className="flex items-start justify-between gap-2">
112	                  <div className="flex min-w-0 items-center gap-3">
113	                    <span className="text-2xl leading-none" aria-hidden>{meta.glyph}</span>
114	                    <div className="min-w-0">
115	                      <p className="truncate font-medium text-slate-100">{s.hostname}</p>
116	                      <p className="mt-0.5 text-xs text-slate-500">
117	                        {meta.name}
118	                        {s.gamePlan ? ` · ${s.gamePlan.name}` : ""}
119	                        {s.gamePlan?.slots ? ` · ${s.gamePlan.slots} slots` : ""}
120	                      </p>
121	                    </div>
122	                  </div>
123	                  <StatusDot status={s.status} />
124	                </div>
125	                <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
126	              </Link>
127	            );
128	          })}
129	        </div>
130	      )}
131	    </>
132	  );
133	}
