67	/**
68	 * Pick the port forward that actually serves a game server's own port, not
69	 * just the first one on the record — a customer can add extra forwards
70	 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
71	 * mistaken for the game's real connect port. Falls back to the first forward
72	 * if none matches, so a server whose family isn't in GAME_PORT (or has no
73	 * exact-matching forward yet) still shows *something* rather than nothing.
74	 * Single shared helper so the provisioning-overlay connect string, the header
75	 * connect string, and the custom-domain DNS instructions can never drift from
76	 * each other the way three independent inline copies previously could.
77	 */
78	function gameForwardFor(server: {
79	  portForwards: { guestPort: number; publicPort: number }[];
80	  osTemplate: { family?: string | null };
81	  gamePlan?: { gameFamily?: string | null } | null;
82	}): { guestPort: number; publicPort: number } | undefined {
83	  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
84	  const expectedPort = family ? GAME_PORT[family]?.port : undefined;
85	  return server.portForwards.find((f) => f.guestPort === expectedPort) ?? server.portForwards[0];
86	}
87	
88	function fmtUptime(seconds: number): string {
89	  if (!seconds || seconds <= 0) return "—";
90	  const d = Math.floor(seconds / 86400);
91	  const h = Math.floor((seconds % 86400) / 3600);
92	  const m = Math.floor((seconds % 3600) / 60);
93	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
94	}
95	
96	type LiveStats = {
97	  cpu?: number;
98	  mem?: number;
99	  maxmem?: number;
100	  uptime?: number;
101	  netin?: number;
102	  netout?: number;
103	} | null;
104	
105	export default async function ServerPage({
106	  params,
107	  searchParams,
108	}: {
109	  params: Promise<{ id: string }>;
110	  searchParams: Promise<{ tab?: string; purchase?: string }>;
111	}) {
112	  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
113	  const user = await requireUser();
114	  const server = await db.server.findUnique({
115	    where: { id },
116	    include: {
117	      plan: true,
118	      osTemplate: true,
119	      project: true,
120	      portForwards: { orderBy: { publicPort: "asc" } },
121	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
122	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
123	      dedicatedIp: true,
124	      node: true,
125	      // Needed to price a renewal correctly: a game server bills its game plan's
126	      // flat price, not the base VPS plan's term price.
127	      gamePlan: true,
128	    },
129	  });
130	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
131	
132	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
133	  // display value through the decrypt fallback (legacy plaintext rows still work).
134	  const rootPassword = serverRootPassword(server);
135	
136	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct, ipMonthlyCentsLive] =
137	    await Promise.all([
138	      db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
139	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
140	      db.osTemplate.findMany({
141	        where: { active: true, category: "PLAIN_OS" },
142	        orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
143	      }),
144	      extraDiskPerGbCents(),
145	      backupPlusMonthlyCents(),
146	      // Live annual discount — feeds the "Renew now" quote below AND the resize
147	      // pickers, so an annual server's renewal/upgrade/downgrade all price against the
148	      // same rate it was sold at.
149	      annualDiscountPct(),
150	      // Fetched unconditionally now (not just `server.dedicatedIp ? … : 0`): the
151	      // "Add dedicated IP" card needs the live price to show a customer who does
152	      // NOT yet have one, same as extraDiskPriceCents above is fetched regardless
153	      // of whether this server currently holds any extra disk.
154	      dedicatedIpMonthlyCents(),
155	    ]);
156	
157	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
158	  const owner =
159	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
160	  const renewTaxCtx = await taxContextForUser(owner);
161	
162	  // What "Renew now" will actually charge, priced through the SAME function the
163	  // action charges through, so the button cannot quote one figure and take
164	  // another. See lib/renewal-quote.ts for the incident.
165	  const renewQuote = renewalQuote(
166	    {
167	      termMonths: server.termMonths,
168	      extraDiskGB: server.extraDiskGB,
169	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
170	      // A game server is sold at its game plan's flat price, NOT the base VPS
171	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
172	      // a $4.99 product.
173	      gamePlan: server.gamePlan
174	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
175	        : null,
176	      dedicatedIp: server.dedicatedIp,
177	      backupTier: server.backupTier,
178	    },
179	    {
180	      ipMonthlyCents: server.dedicatedIp ? ipMonthlyCentsLive : 0,
181	      extraDiskPerGbCents: extraDiskPriceCents,
182	      backupPlusCents,
183	      annualDiscountPct: annualPct,
184	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
185	      // now quote are tax-inclusive, matching what renewNow charges.
186	      taxRatePercent: renewTaxCtx.ratePercent,
187	    },
188	  );
189	
190	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
191	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
192	  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
193	
194	  const publicIp = process.env.PUBLIC_IP ?? "";
195	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
196	  const busy =
197	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
198	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
199	
200	  let live: LiveStats = null;
201	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
202	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
203	  let pveUnavailable = false;
204	
205	  if (server.vmid && steady) {
206	    const results = await Promise.allSettled([
207	      vmStatus(server.vmid),
208	      listSnapshots(server.vmid),
209	      listBackups(server.vmid),
210	    ]);
211	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
212	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
213	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
214	    pveUnavailable = results.some((r) => r.status === "rejected");
215	  }
216	
217	  // Dedicated-IP servers connect straight to their own public IP on port 22; NAT
218	  // servers use the platform public IP + the forwarded SSH port. (A dedicated
219	  // server has sshPort=null, which previously fell through to "provisioning…".)
220	  const sshCommand = server.dedicatedIp
221	    ? `ssh root@${server.dedicatedIp.address}`
222	    : server.sshPort
223	      ? `ssh root@${publicIp} -p ${server.sshPort}`
224	      : null;
225	
226	  // Single-item terminal list for this server — connect string computed the
227	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
228	  const terminalServers = [
229	    {
230	      id: server.id,
231	      hostname: server.hostname,
232	      connect: server.dedicatedIp
233	        ? `ssh root@${server.dedicatedIp.address}`
234	        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
235	    },
236	  ];
237	
238	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
239	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
240	  const dedicated = !!server.dedicatedIp;
241	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
242	  const sftpPort = dedicated ? 22 : server.sshPort;
243	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
244	
245	  // Post-payment "setting up / it's live" interstitial. Connect string mirrors
246	  // the game-branch's own `connect` computation below via the shared
247	  // gameForwardFor() helper, so the two can never drift from each other.
248	  const overlayForward = isGameServer ? gameForwardFor(server) : undefined;
249	  const overlayConnect = isGameServer
250	    ? server.dedicatedIp
251	      ? `${server.dedicatedIp.address}${overlayForward ? `:${overlayForward.guestPort}` : ""}`
252	      : overlayForward
253	        ? `${publicIp}:${overlayForward.publicPort}`
254	        : publicIp || null
255	    : sshCommand;
256	  // Real (not cosmetic) step label when the worker has recorded one for this
257	  // server's CURRENT provisioning run — see lib/provisioning-step.ts. Null while
258	  // transitional but no checkpoint reached yet (or in SANDBOX, which completes
259	  // before any step is ever written) simply falls back to the overlay's existing
260	  // cosmetic cycling text.
261	  const liveStep = transitional ? await serverProvisioningStep(server.id) : null;
262	  const overlay = (
263	    <ProvisioningOverlay
264	      serverId={server.id}
265	      status={server.status}
266	      transitional={transitional}
267	      justPaid={purchase === "1"}
268	      provisionError={server.provisionError}
269	      productLabel={isGameServer ? "game server" : "server"}
270	      hostname={server.hostname}
271	      connectAddress={overlayConnect}
272	      planName={isGameServer ? server.gamePlan?.name ?? server.plan.name : server.plan.name}
273	      osName={server.osTemplate.name}
274	      rootPassword={rootPassword}
275	      liveStep={liveStep}
276	      dashboardHref={`/dashboard/servers/${server.id}`}
277	    />
278	  );
