1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
4	import { getGameLogs, sendGameCommand, gamePower } from "@/lib/actions-game-control";
5	
6	/**
7	 * Console tab — a live terminal over the game process.
8	 *
9	 * Tails logs via getGameLogs (polled), sends console/RCON commands via
10	 * sendGameCommand, and exposes the terminal affordances the card asks for:
11	 * search/filter, clear, auto-scroll toggle, and save/download of the buffer.
12	 * Power (start/restart/stop) is duplicated here for convenience — same guarded
13	 * gamePower action as the header.
14	 */
15	
16	type Line = { text: string; kind: "log" | "cmd" | "out" | "err" };
17	
18	export function GameConsole({ serverId, running }: { serverId: string; running: boolean }) {
19	  const [logLines, setLogLines] = useState<string[]>([]);
20	  const [feed, setFeed] = useState<Line[]>([]);
21	  const [logErr, setLogErr] = useState<string | null>(null);
22	  const [query, setQuery] = useState("");
23	  const [autoScroll, setAutoScroll] = useState(true);
24	  const [rconSupported, setRconSupported] = useState(true);
25	  const [cmd, setCmd] = useState("");
26	  const [msg, setMsg] = useState<string | null>(null);
27	  const [pending, startPower] = useTransition();
28	  const [sending, startSend] = useTransition();
29	  const box = useRef<HTMLDivElement>(null);
30	
31	  const refresh = useCallback(() => {
32	    getGameLogs(serverId).then((r) => {
33	      if (r.ok) {
34	        setLogLines(r.lines);
35	        setLogErr(null);
36	      } else {
37	        setLogErr(r.error);
38	        // The action reports when RCON/console isn't available for the family.
39	        if (/not available|no remote console|disabled/i.test(r.error)) setRconSupported(false);
40	      }
41	    });
42	  }, [serverId]);
43	
44	  useEffect(() => {
45	    if (!running) return;
46	    refresh();
47	    const t = setInterval(refresh, 6000);
48	    return () => clearInterval(t);
49	  }, [running, refresh]);
50	
51	  // Merge the tailed log with the interactive command feed into one stream.
52	  const merged: Line[] = useMemo(() => {
53	    const base: Line[] = logLines.map((text) => ({ text, kind: "log" as const }));
54	    return [...base, ...feed];
55	  }, [logLines, feed]);
56	
57	  const filtered = useMemo(() => {
58	    const q = query.trim().toLowerCase();
59	    if (!q) return merged;
60	    return merged.filter((l) => l.text.toLowerCase().includes(q));
61	  }, [merged, query]);
62	
63	  useEffect(() => {
64	    if (autoScroll && box.current) box.current.scrollTop = box.current.scrollHeight;
65	  }, [filtered, autoScroll]);
66	
67	  function send() {
68	    const c = cmd.trim();
69	    if (!c) return;
70	    setFeed((f) => [...f, { text: `> ${c}`, kind: "cmd" }]);
71	    setCmd("");
72	    startSend(async () => {
73	      const r = await sendGameCommand(serverId, c);
74	      setFeed((f) => [
75	        ...f,
76	        r.ok ? { text: r.response || "(no output)", kind: "out" } : { text: `! ${r.error}`, kind: "err" },
77	      ]);
78	    });
79	  }
80	
81	  function power(action: "start" | "restart" | "stop") {
82	    if (action === "stop" && !window.confirm("Stop the game server? Players will be disconnected.")) return;
83	    setMsg(null);
84	    startPower(async () => {
85	      const r = await gamePower(serverId, action);
86	      setMsg(r.ok ? `${action[0].toUpperCase()}${action.slice(1)} requested — watch the console.` : r.error);
87	    });
88	  }
89	
90	  function download() {
91	    const blob = new Blob([merged.map((l) => l.text).join("\n")], { type: "text/plain" });
92	    const url = URL.createObjectURL(blob);
93	    const a = document.createElement("a");
94	    a.href = url;
95	    a.download = `console-${serverId}-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.log`;
96	    a.click();
97	    URL.revokeObjectURL(url);
98	  }
99	
100	  return (
101	    <div className="space-y-4">
102	      <div className="card p-0">
103	        {/* Toolbar */}
104	        <div className="flex flex-wrap items-center gap-2 border-b border-white/[0.06] px-4 py-3">
105	          <div className="flex items-center gap-2">
106	            <button className="btn-primary px-3 py-1.5 text-xs disabled:opacity-40" disabled={pending || !running} onClick={() => power("start")}>
107	              Start
108	            </button>
109	            <button className="btn-secondary px-3 py-1.5 text-xs disabled:opacity-40" disabled={pending || !running} onClick={() => power("restart")}>
110	              Restart
111	            </button>
112	            <button className="btn-danger px-3 py-1.5 text-xs disabled:opacity-40" disabled={pending || !running} onClick={() => power("stop")}>
113	              Stop
114	            </button>
115	          </div>
116	          <div className="ml-auto flex flex-wrap items-center gap-2">
117	            <input
118	              value={query}
119	              onChange={(e) => setQuery(e.target.value)}
120	              placeholder="Search log…"
121	              className="input h-8 w-40 py-1 text-xs"
122	            />
123	            <button
124	              onClick={() => setAutoScroll((v) => !v)}
125	              className={`rounded-lg border px-2.5 py-1.5 text-xs transition-colors ${
126	                autoScroll ? "border-brand-500/40 bg-brand-500/10 text-brand-200" : "border-white/10 text-slate-400 hover:text-white"
127	              }`}
128	              title="Toggle auto-scroll"
129	            >
130	              Auto-scroll
131	            </button>
132	            <button onClick={() => setFeed([])} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-slate-400 hover:text-white">
133	              Clear
134	            </button>
135	            <button onClick={download} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-slate-400 hover:text-white">
136	              Download
137	            </button>
138	            <button onClick={refresh} disabled={!running} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-slate-400 hover:text-white disabled:opacity-40">
139	              Refresh
140	            </button>
141	          </div>
142	        </div>
143	
144	        {msg && <p className="px-4 pt-3 text-xs text-slate-300">{msg}</p>}
145	        {logErr && <p className="px-4 pt-3 text-xs text-amber-300">{logErr}</p>}
146	
147	        {/* Terminal */}
148	        <div
149	          ref={box}
150	          className="h-[460px] overflow-auto bg-navy-950/80 p-4 font-mono text-[12px] leading-relaxed"
151	        >
152	          {filtered.length === 0 ? (
153	            <p className="text-slate-500">{running ? "Waiting for output…" : "Start the server to stream the console."}</p>
154	          ) : (
155	            filtered.map((l, i) => (
156	              <div
157	                key={i}
158	                className={
159	                  l.kind === "cmd"
160	                    ? "text-brand-300"
161	                    : l.kind === "err"
162	                      ? "text-red-400"
163	                      : l.kind === "out"
164	                        ? "text-accent-cyan"
165	                        : "text-slate-300"
166	                }
167	              >
168	                {l.text}
169	              </div>
170	            ))
171	          )}
172	        </div>
173	
174	        {/* Command input */}
175	        <div className="flex items-center gap-2 border-t border-white/[0.06] px-4 py-3">
176	          <span className="font-mono text-sm text-brand-400">&gt;</span>
177	          <input
178	            className="input flex-1 font-mono text-xs"
179	            placeholder={rconSupported ? "Type a console/RCON command (e.g. say hello)…" : "Console commands are not available for this game"}
180	            value={cmd}
181	            disabled={!rconSupported || sending || !running}
182	            onChange={(e) => setCmd(e.target.value)}
183	            onKeyDown={(e) => e.key === "Enter" && send()}
184	          />
185	          <button className="btn-primary px-4 py-2 text-sm disabled:opacity-40" disabled={!rconSupported || sending || !running || !cmd.trim()} onClick={send}>
186	            {sending ? "Sending…" : "Send"}
187	          </button>
188	        </div>
189	      </div>
190	      {!rconSupported && (
191	        <p className="text-xs text-slate-500">
192	          The command box is disabled because this game has no wired remote-console protocol — log streaming and power still work.
193	        </p>
194	      )}
195	    </div>
196	  );
197	}
