124	export function GameCommandLibrary({ serverId, running }: { serverId: string; running: boolean }) {
125	  const [search, setSearch] = useState("");
126	  const [activeCat, setActiveCat] = useState<string | null>(null);
127	  const [copied, setCopied] = useState<string | null>(null);
