129	  const [pending, startExec] = useTransition();
130	
131	  const filtered = useMemo(() => {
132	    const q = search.trim().toLowerCase();
133	    if (!q && !activeCat) return CATEGORIES;
134	    return CATEGORIES.map((cat) => {
135	      if (activeCat && cat.key !== activeCat) return null;
136	      const cmds = cat.commands.filter(
137	        (c) => !q || c.name.toLowerCase().includes(q) || c.syntax.toLowerCase().includes(q) || c.description.toLowerCase().includes(q)
138	      );
139	      return cmds.length ? { ...cat, commands: cmds } : null;
140	    }).filter(Boolean) as Category[];
141	  }, [search, activeCat]);
142	
143	  const totalResults = filtered.reduce((sum, c) => sum + c.commands.length, 0);
