3	import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
4	import { getServerMods, installMod, uninstallMod, type CatalogMod } from "@/lib/actions-mods";
5	
6	/**
7	 * Mod Store — the panel's differentiator. An App-Store-style browse experience
8	 * over the per-game mod/plugin catalog (GameMod), with a detail view and a
9	 * version → confirm install flow.
10	 *
11	 * REAL backend: catalog + install state + install/uninstall come from
12	 * lib/actions-mods.ts (state-driven GAME_MOD_SYNC job). DERIVED/illustrative
13	 * (clearly labelled in the UI): star rating, install counts, screenshots,
14	 * version history, reviews and changelog — the GameMod model has no such fields
15	 * yet, so they are computed deterministically from the mod's slug so the
16	 * storefront feels alive. The version dropdown is display-only: the installer
17	 * always applies the latest compatible build (see the note in the install modal).
18	 *
19	 * `scope="plugins"` reframes the same catalog toward loader plugins (admin,
20	 * protection, economy, chat, permissions…), falling back to the full catalog
21	 * with a note when a family draws no plugin categories.
22	 */
23	
24	const PLUGIN_KEYWORDS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport"];
25	
26	// ---- deterministic "storefront" meta (illustrative, derived from slug) ----
27	function hash(s: string): number {
28	  let h = 2166136261;
29	  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
30	  return h >>> 0;
31	}
32	function ratingFor(m: CatalogMod): number {
33	  return 4 + ((hash(m.slug) % 11) / 10); // 4.0 – 5.0
34	}
35	function installsFor(m: CatalogMod): number {
36	  const base = 800 + (hash(m.slug) % 90000);
37	  return m.featured ? base * 4 + 120000 : base;
38	}
39	function fmtInstalls(n: number): string {
40	  if (n >= 1000) return `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k`;
41	  return String(n);
42	}
43	function versionsFor(m: CatalogMod): string[] {
44	  const h = hash(m.slug);
45	  const major = 1 + (h % 4);
46	  const minor = h % 12;
47	  return [`Latest (v${major}.${minor})`, `v${major}.${Math.max(0, minor - 1)}`, `v${major - 1 >= 1 ? major - 1 : 1}.9`];
48	}
49	function reviewsFor(m: CatalogMod): { author: string; stars: number; body: string }[] {
50	  const h = hash(m.slug);
51	  const authors = ["RustLegend", "AdminAce", "SurvivalKing", "ModHoarder", "PvPMaster"];
52	  return [
53	    { author: authors[h % authors.length], stars: 5, body: "Rock solid — installed in one click and it just worked on our server." },
54	    { author: authors[(h >> 3) % authors.length], stars: 4, body: "Great feature set. Slight config learning curve but well worth it." },
55	  ];
56	}
57	
58	type SortKey = "popular" | "rating" | "name";
59	
60	export function ModStore({
61	  serverId,
62	  scope,
