32	/** Deterministic gradient for types that have no art yet, so the fallback still
33	 *  looks like a considered card rather than a missing asset. */
34	function fallbackGradient(key: string): string {
35	  const palettes = [
36	    "from-brand-700 via-brand-500 to-accent-blue",
37	    "from-navy-800 via-brand-600 to-accent-cyan",
38	    "from-brand-800 via-accent-blue to-brand-400",
39	  ];
40	  let h = 0;
41	  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
42	  return palettes[h % palettes.length];
43	}
