30	function formatLastPlayed(value: string | null): string {
31	  if (!value) return "Never played";
32	  const d = new Date(value);
33	  if (Number.isNaN(d.getTime())) return "Never played";
34	  const mins = Math.floor((Date.now() - d.getTime()) / 60_000);
35	  if (mins < 1) return "Played just now";
36	  if (mins < 60) return `Played ${mins}m ago`;
37	  const hours = Math.floor(mins / 60);
38	  if (hours < 24) return `Played ${hours}h ago`;
39	  const days = Math.floor(hours / 24);
40	  if (days < 30) return `Played ${days}d ago`;
41	  return `Played ${d.toLocaleDateString()}`;
42	}
