40	function fmtBytes(n: number): string {
41	  if (!n) return "0 B";
42	  const u = ["B", "KB", "MB", "GB", "TB"];
43	  const i = Math.min(Math.floor(Math.log(n) / Math.log(1024)), u.length - 1);
44	  return `${(n / 1024 ** i).toFixed(i ? 1 : 0)} ${u[i]}`;
45	}
