3	import { useState, useTransition } from "react";
4	import { cancelService } from "@/lib/actions-server-lifecycle";
5	
6	/**
7	 * Danger-zone control for self-serve cancellation (Finding 2). Offers the two
8	 * server-side modes — cancel at period end (stop auto-renew, keep to expiry) and
9	 * immediate termination (destroy now, prorated refund to wallet) — behind an explicit
10	 * confirm that states the data-retention consequence and the refund figure.
11	 */
12	export function CancelService({
13	  serverId,
14	  hostname,
15	  expiresAt,
16	  autoRenew,
17	  refundEstimateCents,
18	}: {
19	  serverId: string;
20	  hostname: string;
21	  /** ISO date; null for a free/no-term server (period-end is not offered then). */
22	  expiresAt: string | null;
23	  autoRenew: boolean;
24	  /** Prorated refund the customer would get on IMMEDIATE termination, in cents. */
25	  refundEstimateCents: number;
26	}) {
27	  const [open, setOpen] = useState(false);
28	  const [pending, startTransition] = useTransition();
29	  const [error, setError] = useState<string | null>(null);
30	  const [done, setDone] = useState<string | null>(null);
31	
32	  const money = (c: number) => `$${(c / 100).toFixed(2)}`;
33	  const expiryLabel = expiresAt ? new Date(expiresAt).toISOString().slice(0, 10) : null;
34	
35	  const run = (mode: "immediate" | "period_end") => {
36	    if (mode === "immediate") {
37	      const msg =
38	        `Immediately terminate ${hostname}? This destroys the server and PERMANENTLY erases all its data — this cannot be undone.` +
39	        (refundEstimateCents > 0
40	          ? `\n\n${money(refundEstimateCents)} for the unused part of your term will be credited to your wallet.`
41	          : "\n\nNo refund applies (nothing left on the paid term).");
42	      if (!window.confirm(msg)) return;
43	    }
44	    setError(null);
45	    setDone(null);
46	    startTransition(async () => {
47	      const res = await cancelService(serverId, mode);
48	      if (res?.error) setError(res.error);
49	      else if (res?.message) {
50	        setDone(res.message);
51	        setOpen(false);
52	      }
53	    });
54	  };
55	
56	  if (done) {
57	    return (
58	      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2.5 text-xs text-emerald-200">
59	        {done}
60	      </div>
61	    );
62	  }
63	
64	  return (
65	    <div className="rounded-lg border border-red-500/20 bg-red-500/[0.03] p-4">
66	      <div className="flex flex-wrap items-center justify-between gap-3">
67	        <div>
68	          <p className="text-sm font-semibold text-red-200">Cancel this service</p>
69	          <p className="mt-0.5 text-xs text-slate-400">
70	            Stop auto-renew and keep it to expiry, or terminate now.
71	          </p>
72	        </div>
73	        {!open && (
74	          <button className="btn-secondary py-1.5" onClick={() => setOpen(true)} disabled={pending}>
75	            Cancel service
76	          </button>
77	        )}
78	      </div>
79	
80	      {open && (
81	        <div className="mt-4 space-y-3">
82	          {expiryLabel && (
