10	/**
11	 * Dynamic per-game settings form. Renders the family schema (grouped fields, the
12	 * right widget per type) plus a variant/loader picker, and persists via
13	 * `saveGameConfig` — which validates, stores the values and enqueues a
14	 * GAME_CONFIG job to apply them.
15	 */
16	export function GameSettings({
17	  serverId,
18	  schema,
19	  variant: initialVariant,
20	  values: initialValues,
21	  disabled,
22	}: {
23	  serverId: string;
24	  schema: FamilySchema;
25	  variant: string;
26	  values: Values;
27	  disabled?: boolean;
28	}) {
29	  const router = useRouter();
30	  const [variant, setVariant] = useState(initialVariant);
31	  const [values, setValues] = useState<Values>(initialValues);
32	  const [error, setError] = useState<string | null>(null);
33	  const [saved, setSaved] = useState(false);
34	  const [pending, start] = useTransition();
35	
36	  // Fields grouped by their `group` heading, preserving declaration order.
37	  const groups = useMemo(() => {
38	    const map = new Map<string, ConfigField[]>();
39	    for (const f of schema.fields) {
40	      if (!map.has(f.group)) map.set(f.group, []);
41	      map.get(f.group)!.push(f);
42	    }
43	    return [...map.entries()];
44	  }, [schema]);
45	
46	  function set(key: string, value: string | number | boolean) {
47	    setValues((v) => ({ ...v, [key]: value }));
48	    setSaved(false);
49	  }
50	
51	  function save() {
52	    start(async () => {
53	      setError(null);
54	      setSaved(false);
55	      const res = await saveGameConfig(serverId, variant, values);
56	      if (res?.error) setError(res.error);
57	      else {
58	        setSaved(true);
59	        router.refresh();
60	      }
61	    });
62	  }
63	
64	  const activeVariant = schema.variants.find((v) => v.id === variant);
65	
66	  return (
67	    <div className="card">
68	      <div className="flex flex-wrap items-start justify-between gap-4">
69	        <div>
70	          <h2 className="font-semibold">Game settings</h2>
71	          <p className="mt-1 max-w-xl text-sm text-slate-400">
72	            Configure your {schema.label} server. Changes are queued and applied to the server —
73	            some settings only take effect after the next restart.
74	          </p>
75	        </div>
76	        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
77	          {pending ? "Saving…" : "Save & apply"}
78	        </button>
