1	"use client";
2	
3	import { useState } from "react";
4	
5	/** Snapshot thresholds — instantaneous values already computed on the page, not a
6	 * "sustained N minutes" tracker. Simple on purpose (see ProvisionErrorBanner /
7	 * BackupTierUpsell for the same "small presentational banner" convention). */
8	const RAM_THRESHOLD_PCT = 90;
9	const DISK_THRESHOLD_PCT = 90;
10	const CPU_THRESHOLD_PCT = 90;
11	
12	/**
13	 * "You're running low on X — consider upgrading" banner. Pure presentational:
14	 * renders nothing if every metric is below its threshold, and nothing if a
15	 * metric wasn't supplied (undefined/null — e.g. VPS overview has no per-page
16	 * disk sample, so `diskPct` is simply omitted there rather than faked).
17	 *
18	 * Dismissible for the current page view only (local state, no persistence) —
19	 * this is a nudge, not a notification center entry.
20	 */
21	export function ResourceLimitAlert({
22	  cpuPct,
23	  memPct,
24	  diskPct,
25	  upgradeHref,
26	}: {
27	  cpuPct?: number | null;
28	  memPct?: number | null;
29	  diskPct?: number | null;
30	  /** Where "Upgrade" should take the customer — the resize/storage section. */
31	  upgradeHref: string;
32	}) {
33	  const [dismissed, setDismissed] = useState(false);
34	
35	  const hot: string[] = [];
36	  if (typeof cpuPct === "number" && cpuPct >= CPU_THRESHOLD_PCT) hot.push("CPU");
37	  if (typeof memPct === "number" && memPct >= RAM_THRESHOLD_PCT) hot.push("RAM");
38	  if (typeof diskPct === "number" && diskPct >= DISK_THRESHOLD_PCT) hot.push("disk");
39	
40	  if (dismissed || hot.length === 0) return null;
41	
42	  const label = hot.length === 1 ? hot[0] : hot.length === 2 ? hot.join(" and ") : `${hot.slice(0, -1).join(", ")} and ${hot[hot.length - 1]}`;
43	
44	  return (
45	    <div className="card flex flex-wrap items-center justify-between gap-3 border-amber-500/30 bg-amber-500/[0.06]">
46	      <div className="flex items-start gap-3">
47	        <span className="mt-0.5 text-amber-300">⚠</span>
48	        <div>
49	          <p className="text-sm font-medium text-amber-200">
50	            Running low on {label}
51	          </p>
52	          <p className="mt-0.5 text-xs text-slate-400">
53	            Your server is using {hot.length > 1 ? "most" : "nearly all"} of its {label} — consider
54	            upgrading to a bigger plan before it becomes a bottleneck.
55	          </p>
56	        </div>
57	      </div>
58	      <div className="flex shrink-0 items-center gap-2">
59	        <a href={upgradeHref} className="btn-secondary text-xs">
60	          Upgrade
61	        </a>
62	        <button
63	          type="button"
64	          onClick={() => setDismissed(true)}
65	          className="rounded-full px-2 py-1 text-xs text-slate-500 hover:text-slate-300"
66	          aria-label="Dismiss"
67	        >
68	          Dismiss
69	        </button>
70	      </div>
71	    </div>
72	  );
73	}
