33	function RequestCertificate({ servers }: { servers: ServerOption[] }) {
34	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
35	  const [domain, setDomain] = useState("");
36	  const [error, setError] = useState<string | null>(null);
37	  const [pending, start] = useTransition();
38	
39	  const noServers = servers.length === 0;
40	
41	  return (
42	    <div className="card p-5">
43	      <h3 className="text-base font-semibold">Request a certificate</h3>
44	      <p className="mt-1 text-sm text-slate-400">
45	        Point your domain&apos;s DNS at the server first, then request a free Let&apos;s Encrypt
46	        certificate. Issuance usually completes within a minute.
47	      </p>
48	      <div className="mt-4 flex flex-wrap items-end gap-3">
49	        <div>
50	          <label className="label">Server</label>
51	          <select
52	            className="input w-52"
53	            value={serverId}
54	            onChange={(e) => setServerId(e.target.value)}
55	            disabled={pending || noServers}
56	          >
57	            {noServers ? (
58	              <option value="">No running servers</option>
59	            ) : (
60	              servers.map((s) => (
61	                <option key={s.id} value={s.id}>
62	                  {s.hostname}
63	                </option>
64	              ))
65	            )}
66	          </select>
67	        </div>
68	        <div>
69	          <label className="label">Domain</label>
70	          <input
71	            className="input w-64"
72	            value={domain}
73	            onChange={(e) => setDomain(e.target.value)}
74	            placeholder="app.example.com"
75	            disabled={pending || noServers}
76	          />
77	        </div>
78	        <button
79	          className="btn-primary"
80	          disabled={pending || noServers || !serverId || domain.trim().length < 3}
81	          onClick={() =>
82	            start(async () => {
83	              setError(null);
84	              const res = await requestCertificate(serverId, domain.trim());
85	              if (res?.error) setError(res.error);
86	              else setDomain("");
87	            })
88	          }
89	        >
90	          {pending ? "Requesting…" : "Request certificate"}
91	        </button>
92	      </div>
93	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
94	      {noServers && (
95	        <p className="mt-2 text-xs text-slate-500">
96	          You need a running server before you can request a certificate.
97	        </p>
98	      )}
99	    </div>
100	  );
101	}
