173	      {certificates.length === 0 ? (
174	        <div className="card p-8 text-center text-sm text-slate-400">
175	          No certificates yet. Request one above to enable HTTPS on a domain pointed at your server.
176	        </div>
177	      ) : (
178	        <div className="card overflow-x-auto p-0">
179	          <table className="table-shell">
180	            <thead>
181	              <tr>
182	                <th>Domain</th>
183	                <th>Server</th>
184	                <th>Status</th>
185	                <th>Expires</th>
186	                <th>Auto-renew &amp; actions</th>
187	              </tr>
188	            </thead>
189	            <tbody>
190	              {certificates.map((c) => (
191	                <tr key={c.id}>
192	                  <td className="font-medium text-slate-100">
193	                    {c.domain}
194	                    {c.status === "FAILED" && c.lastError && (
195	                      <span className="mt-0.5 block text-xs font-normal text-red-400">
196	                        {c.lastError}
197	                      </span>
198	                    )}
199	                  </td>
200	                  <td className="text-slate-400">{c.serverName ?? "—"}</td>
201	                  <td>
202	                    <StatusDot status={c.status} />
203	                  </td>
204	                  <td className="text-slate-400">{fmtDate(c.expiresAt)}</td>
205	                  <td>
206	                    <CertActions cert={c} />
207	                  </td>
208	                </tr>
209	              ))}
210	            </tbody>
211	          </table>
212	        </div>
213	      )}
214	    </div>
215	  );
216	}
