1	"use client";
2	
3	import {
4	  forwardRef,
5	  useEffect,
6	  useImperativeHandle,
7	  useMemo,
8	  useRef,
9	  useState,
10	} from "react";
11	import { createPortal } from "react-dom";
12	import type { Terminal as XTerm } from "@xterm/xterm";
13	import type { FitAddon as XFitAddon } from "@xterm/addon-fit";
14	import "@xterm/xterm/css/xterm.css";
15	
16	/**
17	 * In-portal web terminal — a slide-in panel with an xterm.js terminal wired to
18	 * a real root shell on one of the customer's running servers.
19	 *
20	 * Security: the websocket is authorized by a short-lived token minted by
21	 * POST /api/terminal/token (which checks the session + ownership). This
22	 * component never sees any server credential — only the opaque token.
23	 *
24	 * Wire protocol (matches terminal-server/index.ts):
25	 *   client → server : JSON  {type:"data",data} | {type:"resize",cols,rows}
26	 *   server → client : raw shell output (text or binary) → written to xterm
27	 */
28	
29	export type TerminalServer = { id: string; hostname: string };
30	
31	type Status = "idle" | "connecting" | "connected" | "closed" | "error";
32	
33	/**
34	 * Imperative handle exposed to parents (e.g. the Matrix console's rich input
35	 * bar). `sendInput` injects text straight into the live PTY exactly as if the
36	 * user had typed it, so the parent's send box can drive the `claude` CLI.
37	 */
38	export type WebTerminalHandle = {
39	  /** Type `text` into the live PTY. No-op if the socket is not open. */
40	  sendInput: (text: string) => void;
41	  /** Whether the PTY websocket is currently open. */
42	  isConnected: () => boolean;
43	};
44	
45	type WebTerminalProps = {
46	  servers: TerminalServer[];
47	  /** Overlay mode only. Optional in embedded mode (no chrome to close). */
48	  onClose?: () => void;
49	  /**
50	   * When true, render inline (fills its parent) instead of as a full-screen
51	   * slide-in portal. Used to give each Matrix console its own terminal.
52	   */
53	  embedded?: boolean;
54	  /** Optional one-line idle hint shown before the first connect. */
55	  hint?: string;
56	};
57	
58	export const WebTerminal = forwardRef<WebTerminalHandle, WebTerminalProps>(function WebTerminal(
59	  { servers, onClose, embedded = false, hint },
60	  ref
61	) {
62	  const [mounted, setMounted] = useState(false);
63	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
64	  const [status, setStatus] = useState<Status>("idle");
65	  const [error, setError] = useState<string | null>(null);
66	  const [hintDismissed, setHintDismissed] = useState(false);
67	
68	  const hostRef = useRef<HTMLDivElement | null>(null);
69	  const termRef = useRef<XTerm | null>(null);
70	  const fitRef = useRef<XFitAddon | null>(null);
71	  const wsRef = useRef<WebSocket | null>(null);
72	  const roRef = useRef<ResizeObserver | null>(null);
73	  const disposedRef = useRef(false);
74	
75	  useEffect(() => {
76	    setMounted(true);
77	    return () => {
78	      disposedRef.current = true;
79	    };
80	  }, []);
81	
82	  const selected = useMemo(
83	    () => servers.find((s) => s.id === serverId) ?? null,
84	    [servers, serverId]
85	  );
86	
87	  /**
88	   * Expose programmatic input injection to parents. `sendInput` writes to the
89	   * PTY using the EXACT same wire frame as an interactive keystroke
90	   * (`{type:"data",data}`) — the input bar and the keyboard are indistinguishable
91	   * to the backend. Guarded on an open socket so a message typed before Connect
92	   * (or after Disconnect) is silently dropped rather than throwing.
93	   */
94	  useImperativeHandle(
95	    ref,
96	    () => ({
97	      sendInput: (text: string) => {
98	        const ws = wsRef.current;
99	        if (ws && ws.readyState === WebSocket.OPEN) {
100	          ws.send(JSON.stringify({ type: "data", data: text }));
101	        }
102	      },
103	      isConnected: () => wsRef.current?.readyState === WebSocket.OPEN,
104	    }),
105	    []
106	  );
107	
108	  /** Tear down the live websocket + terminal (idempotent). */
109	  function teardown() {
110	    try {
111	      roRef.current?.disconnect();
112	    } catch {
113	      /* ignore */
114	    }
115	    roRef.current = null;
116	    try {
117	      wsRef.current?.close();
118	    } catch {
119	      /* ignore */
120	    }
121	    wsRef.current = null;
122	    try {
123	      termRef.current?.dispose();
124	    } catch {
125	      /* ignore */
126	    }
127	    termRef.current = null;
128	    fitRef.current = null;
129	  }
130	
131	  useEffect(() => {
132	    // Clean up whenever the panel unmounts.
133	    return () => teardown();
134	    // eslint-disable-next-line react-hooks/exhaustive-deps
135	  }, []);
136	
137	  function sendResize() {
138	    const term = termRef.current;
139	    const fit = fitRef.current;
140	    const ws = wsRef.current;
141	    if (!term || !fit) return;
142	    try {
143	      fit.fit();
144	    } catch {
145	      /* ignore */
146	    }
147	    if (ws && ws.readyState === WebSocket.OPEN) {
148	      ws.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
149	    }
150	  }
151	
152	  async function connect() {
153	    if (!serverId) return;
154	    setError(null);
155	    setStatus("connecting");
156	    teardown();
157	
158	    // 1. Mint a short-lived token (session + ownership checked server-side).
159	    let token: string;
160	    try {
161	      const res = await fetch("/api/terminal/token", {
162	        method: "POST",
163	        headers: { "Content-Type": "application/json" },
164	        body: JSON.stringify({ serverId }),
165	      });
166	      const body = await res.json().catch(() => ({}));
167	      if (!res.ok) throw new Error(body?.error || "Could not authorize the terminal.");
168	      token = body.token;
169	      if (!token) throw new Error("No terminal token was issued.");
170	    } catch (e) {
171	      setStatus("error");
172	      setError(e instanceof Error ? e.message : "Could not authorize the terminal.");
173	      return;
174	    }
175	    if (disposedRef.current) return;
176	
177	    // 2. Build the terminal.
178	    const [{ Terminal }, { FitAddon }] = await Promise.all([
179	      import("@xterm/xterm"),
180	      import("@xterm/addon-fit"),
181	    ]);
182	    if (disposedRef.current || !hostRef.current) return;
183	
184	    const term = new Terminal({
185	      cursorBlink: true,
186	      fontFamily:
187	        'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace',
188	      fontSize: 13,
189	      theme: { background: "#0a0e1a", foreground: "#e2e8f0", cursor: "#e2e8f0" },
190	    });
191	    const fit = new FitAddon();
192	    term.loadAddon(fit);
193	    term.open(hostRef.current);
194	    try {
195	      fit.fit();
196	    } catch {
197	      /* ignore */
198	    }
199	    termRef.current = term;
200	    fitRef.current = fit;
201	
202	    // 3. Open the websocket to the PTY backend (nginx proxies /terminal-ws).
203	    const scheme = location.protocol === "https:" ? "wss" : "ws";
204	    const ws = new WebSocket(
205	      `${scheme}://${location.host}/terminal-ws?token=${encodeURIComponent(token)}`
206	    );
207	    ws.binaryType = "arraybuffer";
208	    wsRef.current = ws;
209	
210	    ws.onopen = () => {
211	      setStatus("connected");
212	      term.focus();
213	      sendResize();
214	    };
215	    ws.onmessage = (ev) => {
216	      if (typeof ev.data === "string") {
217	        term.write(ev.data);
218	      } else if (ev.data instanceof ArrayBuffer) {
219	        term.write(new Uint8Array(ev.data));
220	      }
221	    };
222	    ws.onerror = () => {
223	      setError("Connection error.");
224	    };
225	    ws.onclose = (ev) => {
226	      setStatus((s) => (s === "error" ? s : "closed"));
227	      if (ev.reason && termRef.current) {
228	        term.write(`\r\n\x1b[90m[${ev.reason}]\x1b[0m\r\n`);
229	      }
230	    };
231	
232	    // 4. Keystrokes → server.
233	    term.onData((data) => {
234	      if (ws.readyState === WebSocket.OPEN) {
235	        ws.send(JSON.stringify({ type: "data", data }));
236	      }
237	    });
238	
239	    // 5. Keep the PTY window sized to the panel.
240	    const ro = new ResizeObserver(() => sendResize());
241	    if (hostRef.current) ro.observe(hostRef.current);
242	    roRef.current = ro;
243	  }
244	
245	  function disconnect() {
246	    teardown();
247	    setStatus("closed");
248	  }
249	
250	  const statusLabel: Record<Status, string> = {
251	    idle: "Not connected",
252	    connecting: "Connecting…",
253	    connected: "Connected",
254	    closed: "Disconnected",
255	    error: "Error",
256	  };
257	  const statusColor: Record<Status, string> = {
258	    idle: "bg-slate-500",
259	    connecting: "bg-amber-400 animate-pulse",
260	    connected: "bg-emerald-400",
261	    closed: "bg-slate-500",
262	    error: "bg-red-500",
263	  };
264	  const live = status === "connected" || status === "connecting";
265	
266	  if (!mounted) return null;
267	
268	  const body = (
269	    <>
270	        {/* Header */}
271	        <div className="flex flex-none items-center gap-3 border-b border-white/[0.06] px-4 py-3">
272	          <div className="flex items-center gap-2">
273	            <span className={`h-2.5 w-2.5 rounded-full ${statusColor[status]}`} />
274	            <span className="text-sm font-semibold text-white">Terminal</span>
275	            <span className="text-xs text-slate-400">{statusLabel[status]}</span>
276	          </div>
277	
278	          <div className="ml-auto flex items-center gap-2">
279	            {/* Embedded mode gets its server from the parent console's own
280	                picker (servers={[server]}), so the in-terminal dropdown is
281	                redundant there — only render it in overlay/standalone mode. */}
282	            {!embedded && (
283	              <select
284	                value={serverId}
285	                onChange={(e) => setServerId(e.target.value)}
286	                disabled={live}
287	                className="max-w-[10rem] rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5 text-xs text-white outline-none focus:border-brand-400/60 disabled:opacity-50"
288	              >
289	                {servers.length === 0 && <option value="">No running servers</option>}
290	                {servers.map((s) => (
291	                  <option key={s.id} value={s.id} className="bg-navy-900">
292	                    {s.hostname}
293	                  </option>
294	                ))}
295	              </select>
296	            )}
297	
298	            {live ? (
299	              <button
300	                onClick={disconnect}
301	                className="rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 text-xs font-semibold text-slate-200 hover:bg-white/10"
302	              >
303	                Disconnect
304	              </button>
305	            ) : (
306	              <button
307	                onClick={connect}
308	                disabled={!serverId}
309	                className="rounded-lg bg-brand-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-400 disabled:opacity-50"
310	              >
311	                Connect
312	              </button>
313	            )}
314	
315	            {onClose && (
316	              <button
317	                onClick={onClose}
318	                className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white"
319	                aria-label="Close terminal"
320	              >
321	                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
322	                  <path d="M18 6 6 18M6 6l12 12" />
323	                </svg>
324	              </button>
325	            )}
326	          </div>
327	        </div>
328	
329	        {/* Error banner */}
330	        {error && (
331	          <div className="flex-none border-b border-red-500/20 bg-red-500/10 px-4 py-2 text-xs text-red-200">
332	            {error}
333	          </div>
334	        )}
335	
336	        {/* Hint before first connect — dismissible with the X. */}
337	        {status === "idle" && !hintDismissed && (
338	          <div className="flex flex-none items-start gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2 text-xs text-slate-400">
339	            <div className="min-w-0 flex-1">
340	              {hint
341	                ? hint
342	                : selected
343	                  ? <>Opens a root shell on <span className="font-semibold text-slate-200">{selected.hostname}</span>. Run <code className="rounded bg-white/10 px-1 text-slate-200">claude</code> to start building.</>
344	                  : "Pick a running server, then press Connect."}
345	            </div>
346	            <button
347	              type="button"
348	              onClick={() => setHintDismissed(true)}
349	              className="flex-none rounded p-0.5 text-slate-500 hover:bg-white/10 hover:text-white"
350	              aria-label="Dismiss hint"
351	              title="Dismiss"
352	            >
353	              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round">
354	                <path d="M18 6 6 18M6 6l12 12" />
355	              </svg>
356	            </button>
357	          </div>
358	        )}
359	
360	        {/* Terminal surface */}
361	        <div className="min-h-0 flex-1 bg-[#0a0e1a] p-2">
362	          <div ref={hostRef} className="h-full w-full" />
363	        </div>
364	    </>
365	  );
366	
367	  // Embedded: render inline, filling the console pane. No portal, no backdrop.
368	  if (embedded) {
369	    return (
370	      <div className="flex h-full min-h-0 flex-col overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-900/70">
371	        {body}
372	      </div>
373	    );
374	  }
375	
376	  // Overlay: full-screen slide-in panel.
377	  return createPortal(
378	    <div className="fixed inset-0 z-[70] flex justify-end" role="dialog" aria-modal="true">
379	      {/* Backdrop */}
380	      <div
