3	/**
4	 * Player-inventory editor for the free Minecraft Players tab.
5	 *
6	 * READ THIS BEFORE CHANGING THE COPY: vanilla RCON has no "read a player's
7	 * inventory" command — the only primitive is a write-only
8	 * `/item replace entity <player> <slot> with <item>[<count>]`. This UI is
9	 * deliberately NOT a live view of what's in someone's inventory; it's a
10	 * "set this slot to become X" tool. Every slot control below starts blank/
11	 * unselected on every render — it never claims to reflect current contents.
12	 *
13	 * UI NOTE: slots render as icon tiles (see ItemIcon.tsx for where those
14	 * icons come from and why — short version: hand-authored original SVG
15	 * glyphs, not Minecraft textures, because a properly-licensed source of
16	 * real item renders wasn't available for commercial use — see that file's
17	 * header for the full explanation). Clicking a tile opens a searchable
18	 * icon-grid picker instead of a 392-row text dropdown.
19	 */
20	import { useEffect, useMemo, useState, useTransition } from "react";
21	import { getFreeMinecraftPlayers } from "@/lib/actions-free-minecraft";
22	import { applyPlayerInventoryEdit, type ApplyInventoryEditState } from "@/lib/actions-freemc-inventory";
23	import { MINECRAFT_ITEMS, MINECRAFT_ITEM_CATEGORIES, type MinecraftItem } from "@/lib/minecraft-items";
