29	const CLEAR_ID = "minecraft:air";
30	const CLEAR_ITEM = MINECRAFT_ITEMS.find((it) => it.id === CLEAR_ID)!;
31	
32	export function InventoryEditor({ running }: { running: boolean }) {
33	  const [players, setPlayers] = useState<{ name: string }[] | null>(null);
34	  const [playersError, setPlayersError] = useState<string | null>(null);
35	  const [player, setPlayer] = useState<string>("");
36	  const [edits, setEdits] = useState<Record<string, PendingEdit>>({});
37	  const [result, setResult] = useState<ApplyInventoryEditState | null>(null);
38	  const [pending, startTransition] = useTransition();
39	  const [refreshing, startRefresh] = useTransition();
40	  const [pickerSlot, setPickerSlot] = useState<SlotDef | null>(null);
41	
42	  function refreshPlayers() {
43	    startRefresh(async () => {
44	      const res = await getFreeMinecraftPlayers();
45	      if (res.ok) {
46	        setPlayers(res.players);
47	        setPlayersError(null);
48	        if (!res.players.some((p) => p.name === player)) setPlayer(res.players[0]?.name ?? "");
49	      } else {
50	        setPlayersError(res.error);
51	        setPlayers(null);
52	      }
53	    });
54	  }
55	  useEffect(() => {
56	    if (running) refreshPlayers();
57	    // eslint-disable-next-line react-hooks/exhaustive-deps
58	  }, [running]);
59	
60	  function setSlot(slot: string, next: Partial<PendingEdit>) {
61	    setEdits((prev) => {
62	      const current = prev[slot] ?? { itemId: "", count: 1 };
63	      const merged = { ...current, ...next };
64	      // Dropping back to "no item chosen" removes the pending edit entirely
65	      // rather than submitting a no-op.
66	      if (!merged.itemId) {
67	        const { [slot]: _drop, ...rest } = prev;
68	        return rest;
69	      }
70	      return { ...prev, [slot]: merged };
71	    });
72	  }
73	
74	  const pendingCount = Object.keys(edits).length;
75	
76	  function submit() {
77	    if (!player || pendingCount === 0) return;
78	    const payload = Object.entries(edits).map(([slot, e]) => ({
79	      slot,
80	      itemId: e.itemId,
81	      count: e.itemId === CLEAR_ID ? 1 : e.count,
82	    }));
83	    const fd = new FormData();
84	    fd.set("player", player);
85	    fd.set("edits", JSON.stringify(payload));
86	    startTransition(async () => {
87	      const res = await applyPlayerInventoryEdit({}, fd);
88	      setResult(res);
89	      if (!res.error) setEdits({});
90	    });
91	  }
92	
93	  return (
94	    <div className="card space-y-5">
95	      <div>
96	        <h3 className="font-semibold text-[var(--fg)]">Give items</h3>
97	        <p className="mt-1 text-sm text-slate-400">
98	          Minecraft doesn&apos;t let us read what&apos;s currently in a player&apos;s inventory over RCON — this tool only
99	          <span className="text-slate-300"> sets</span> slots to whatever you pick below. It doesn&apos;t show current
100	          contents, and picking a slot below will overwrite whatever&apos;s already there.
101	        </p>
102	      </div>
103	
104	      {!running ? (
105	        <p className="text-sm text-slate-500">Server is asleep — nobody&apos;s connected. Wake it up to edit inventories.</p>
106	      ) : (
107	        <>
108	          <div className="flex flex-wrap items-end gap-3">
109	            <div>
110	              <label className="label mb-1 block">Player</label>
111	              <select className="input" value={player} onChange={(e) => setPlayer(e.target.value)} disabled={!players?.length}>
112	                {!players?.length && <option value="">No one online</option>}
113	                {players?.map((p) => (
114	                  <option key={p.name} value={p.name}>
115	                    {p.name}
116	                  </option>
117	                ))}
118	              </select>
119	            </div>
120	            <button type="button" className="btn-ghost text-xs" onClick={refreshPlayers} disabled={refreshing}>

